import { Suspense, useCallback, type CSSProperties } from "react";
import {
  TRAIT_LABELS,
  TRAIT_ORDER,
  assetFor,
  previewUrl,
  requireSpecimen,
  REGISTRY_SPECIMENS,
} from "../content";
import { appStore } from "../state/app-store";
import { useVanillaStore } from "../lib/use-vanilla-store";
import { effectiveReducedMotion, useMediaQuery, useSystemReducedMotion } from "../lib/media";
import { LazyViewerPane } from "../viewer/lazy";
import { ViewerBoundary, ViewerLoadFallback, ViewerSkeleton } from "../components/ViewerBoundary";
import { navigate, navigateToStructure } from "../lib/navigation";
import { IconArrowUpRight, IconChevronRight, IconSwap } from "../components/Icons";
import type { Specimen } from "@cas/content-registry";

export function ComparePage() {
  const compareLeftId = useVanillaStore(appStore, (s) => s.compareLeftId);
  const compareRightId = useVanillaStore(appStore, (s) => s.compareRightId);
  const selectedStructureId = useVanillaStore(appStore, (s) => s.selectedStructureId);
  const reduceMotionPref = useVanillaStore(appStore, (s) => s.settings.reduceMotion);
  const autoRotate = useVanillaStore(appStore, (s) => s.settings.autoRotate);
  const systemReduced = useSystemReducedMotion();
  const reduceMotion = effectiveReducedMotion(reduceMotionPref, systemReduced);
  const wide = useMediaQuery("(min-width: 980px)");
  const left = requireSpecimen(compareLeftId);
  const right = requireSpecimen(compareRightId);
  const sharedIds = left.structures
    .map((structure) => structure.id)
    .filter((id) => right.structures.some((structure) => structure.id === id));
  const sharedFocus =
    selectedStructureId && sharedIds.includes(selectedStructureId) ? selectedStructureId : null;
  const sharedName =
    left.structures.find((structure) => structure.id === sharedFocus)?.name ??
    right.structures.find((structure) => structure.id === sharedFocus)?.name;

  function choose(side: "left" | "right", id: string) {
    appStore.getState().selectCompare(side, id);
    if (appStore.getState().selectedStructureId) appStore.getState().selectStructure(null);
  }

  const handleSelectStructure = useCallback((structureId: string | null) => {
    appStore.getState().selectStructure(structureId);
  }, []);

  return (
    <div className="page page--compare">
      <header className="page-header">
        <div>
          <p className="eyebrow">Side by side</p>
          <h1>Compare two specimens</h1>
          <p className="lede">
            Two isolated scene graphs, one shared structure focus. Traits come from the same content
            registry as the Explore pages.
          </p>
        </div>
        <div className="page-header__controls">
          <button
            type="button"
            className="button button--ghost"
            onClick={() => navigate("explore")}
          >
            Back to Explore
          </button>
        </div>
      </header>

      <div className="compare-controls">
        <SpecimenSelect
          label="Left specimen"
          value={left.id}
          onChange={(id) => choose("left", id)}
        />
        <button
          type="button"
          className="button button--ghost compare-controls__swap"
          onClick={() => appStore.getState().swapCompare()}
          aria-label="Swap sides"
          title="Swap sides"
        >
          <IconSwap />
          <span>Swap sides</span>
        </button>
        <SpecimenSelect
          label="Right specimen"
          value={right.id}
          onChange={(id) => choose("right", id)}
        />
        <label className="field compare-controls__focus">
          <span>Shared structure focus</span>
          <select
            value={sharedFocus ?? ""}
            onChange={(event) => appStore.getState().selectStructure(event.target.value || null)}
          >
            <option value="">No shared focus</option>
            {sharedIds.map((id) => {
              const name =
                left.structures.find((structure) => structure.id === id)?.name ??
                right.structures.find((structure) => structure.id === id)?.name ??
                id;
              return (
                <option key={id} value={id}>
                  {name}
                </option>
              );
            })}
          </select>
        </label>
      </div>

      {sharedName && (
        <p className="muted small compare-focus-note">
          Focusing <strong>{sharedName}</strong> in both models where the registry maps it. A
          structure missing from one specimen is simply not highlighted there.
        </p>
      )}

      {wide ? (
        <div className="compare-grid">
          {(
            [
              { side: "left", specimen: left },
              { side: "right", specimen: right },
            ] as const
          ).map(({ side, specimen }) => (
            <section
              key={`${side}-${specimen.id}`}
              className="compare-column"
              aria-label={specimen.name}
            >
              <div className="compare-column__head">
                <div>
                  <p className="eyebrow eyebrow--with-dot">
                    <span
                      className="specimen-dot"
                      style={{ "--dot-accent": specimen.accent } as CSSProperties}
                      aria-hidden="true"
                    />
                    {specimen.domain}
                  </p>
                  <h2>{specimen.name}</h2>
                </div>
                <button
                  type="button"
                  className="button button--ghost"
                  onClick={() => {
                    appStore.getState().selectSpecimen(specimen.id);
                    navigate("explore");
                  }}
                >
                  <span>Open</span>
                  <IconChevronRight />
                </button>
              </div>
              <ViewerBoundary
                fallback={
                  <ViewerLoadFallback
                    previewPath={previewUrl(specimen.previewPath)}
                    name={specimen.name}
                    message="The comparison viewer could not load. The trait table below is unaffected."
                  />
                }
              >
                <Suspense
                  fallback={
                    <ViewerSkeleton
                      previewPath={previewUrl(specimen.previewPath)}
                      name={specimen.name}
                    />
                  }
                >
                  <LazyViewerPane
                    specimen={specimen}
                    asset={assetFor(specimen)}
                    selectedStructureId={sharedFocus}
                    onSelectStructure={handleSelectStructure}
                    reduceMotion={reduceMotion}
                    autoRotate={autoRotate}
                    compact
                  />
                </Suspense>
              </ViewerBoundary>
              <p className="muted small">{specimen.sizeNote}</p>
            </section>
          ))}
        </div>
      ) : (
        <div className="compare-cards">
          {(
            [
              { side: "left", specimen: left },
              { side: "right", specimen: right },
            ] as const
          ).map(({ side, specimen }) => (
            <article key={`${side}-${specimen.id}`} className="compare-card">
              <img
                src={previewUrl(specimen.previewPath)}
                alt={`${specimen.name} schematic preview`}
                width={640}
                height={640}
              />
              <div>
                <p className="eyebrow">{specimen.domain}</p>
                <h2>{specimen.name}</h2>
                <p>{specimen.summary}</p>
                <button
                  type="button"
                  className="button button--primary"
                  onClick={() => {
                    appStore.getState().selectSpecimen(specimen.id);
                    navigate("explore");
                  }}
                >
                  Open 3D view
                </button>
              </div>
            </article>
          ))}
          <p className="muted small">
            Side-by-side 3D needs a wider screen. The trait table below carries the full comparison
            on small screens.
          </p>
        </div>
      )}

      <TraitTable left={left} right={right} />

      <section className="callout-panel">
        <h2>What comparison can and cannot show</h2>
        <p>
          These are schematic models at a shared display scale, not micrographs. Size notes are
          approximate ranges from the cited sources; organelle counts and spacing are illustrative.
          A missing trait means the cited sources did not support a simple value, not that the
          biology is absent.
        </p>
      </section>
    </div>
  );
}

function SpecimenSelect({
  label,
  value,
  onChange,
}: {
  label: string;
  value: string;
  onChange: (id: string) => void;
}) {
  return (
    <label className="field">
      <span>{label}</span>
      <select value={value} onChange={(event) => onChange(event.target.value)}>
        {REGISTRY_SPECIMENS.map((specimen) => (
          <option key={specimen.id} value={specimen.id}>
            {specimen.name} ({specimen.domain})
          </option>
        ))}
      </select>
    </label>
  );
}

function TraitTable({ left, right }: { left: Specimen; right: Specimen }) {
  return (
    <section className="trait-table" aria-labelledby="trait-heading">
      <div className="section-heading">
        <div>
          <p className="eyebrow">Registry traits</p>
          <h2 id="trait-heading">Trait comparison</h2>
        </div>
        <p className="muted small">
          Every value is authored per specimen and traceable to the cited sources.
        </p>
      </div>
      <div
        className="trait-table__scroll"
        role="region"
        aria-label={`Scrollable trait table comparing ${left.name} and ${right.name}`}
        tabIndex={0}
      >
        <table>
          <caption className="visually-hidden">
            Comparison of {left.name} and {right.name} across cited draft traits
          </caption>
          <thead>
            <tr>
              <th scope="col">Trait</th>
              <th scope="col">
                <span className="table-head-label">
                  <span
                    className="specimen-dot"
                    style={{ "--dot-accent": left.accent } as CSSProperties}
                    aria-hidden="true"
                  />
                  {left.name}
                </span>
              </th>
              <th scope="col">
                <span className="table-head-label">
                  <span
                    className="specimen-dot"
                    style={{ "--dot-accent": right.accent } as CSSProperties}
                    aria-hidden="true"
                  />
                  {right.name}
                </span>
              </th>
            </tr>
          </thead>
          <tbody>
            {TRAIT_ORDER.filter(
              (traitId) =>
                left.traits.some((trait) => trait.id === traitId) ||
                right.traits.some((trait) => trait.id === traitId),
            ).map((traitId) => {
              const leftTrait = left.traits.find((trait) => trait.id === traitId);
              const rightTrait = right.traits.find((trait) => trait.id === traitId);
              const leftFallback =
                left.specimenKind === "organ" ? "Not applicable (organ)" : "Not applicable (cell)";
              const rightFallback =
                right.specimenKind === "organ" ? "Not applicable (organ)" : "Not applicable (cell)";
              const leftVal = leftTrait?.value ?? leftFallback;
              const rightVal = rightTrait?.value ?? rightFallback;
              const differs = leftVal !== rightVal;
              return (
                <tr key={traitId} data-differs={differs}>
                  <th scope="row">{TRAIT_LABELS[traitId]}</th>
                  <td>
                    {leftVal}
                    {leftTrait?.note && <span className="trait-note">{leftTrait.note}</span>}
                  </td>
                  <td>
                    {rightVal}
                    {rightTrait?.note && <span className="trait-note">{rightTrait.note}</span>}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
      <div className="trait-table__actions">
        {(
          [
            { side: "left", specimen: left },
            { side: "right", specimen: right },
          ] as const
        ).map(({ side, specimen }) => (
          <button
            key={`${side}-${specimen.id}`}
            type="button"
            className="button button--ghost"
            onClick={() => {
              const structure = specimen.structures[0];
              if (structure) navigateToStructure(specimen.id, structure.id);
            }}
          >
            <span>Study {specimen.shortName}</span>
            <IconArrowUpRight />
          </button>
        ))}
      </div>
    </section>
  );
}
